--------------------------------------------------------
--  DDL for Package PKG_COMMON
--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE PACKAGE "JOHN"."PKG_COMMON" is

  function get_previous_data(chat_id IN number )
  return clob;

end;
--------------------------------------------------------
--  DDL for Package Body PKG_COMMON
--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE PACKAGE BODY "JOHN"."PKG_COMMON" is

  Function get_previous_data( chat_id IN number )
     RETURN clob
  IS
    lv_result clob;
  BEGIN
    select message_data_clob_out
      into lv_result
      from ( select *
               from john.users_data
              where chat_id  = chat_id
              order by dt_ins desc)
     where rownum = 1;
  RETURN lv_result;

  END;

end;
